-- Этап 2, существа (contract): таблицы действий больше не нужны, данные — в creatures.actions (0011).
-- Rollback восстанавливает таблицы из jsonb с теми же именами FK и индексов, что в baseline,
-- но общих действий уже не будет: у каждого существа свои строки.

--changeset pg-migration:0012-drop-creatures_actions
DROP TABLE creatures_actions;
DROP TABLE creature_actions;
--rollback CREATE TABLE creature_actions (id integer generated by default as identity PRIMARY KEY, action_type smallint CHECK (action_type BETWEEN 0 AND 5), description text COLLATE ci, english_name varchar(255) COLLATE ci, markdown boolean DEFAULT false, name varchar(255) COLLATE ci);
--rollback CREATE TABLE creatures_actions (creature_id integer NOT NULL, actions_id integer NOT NULL, sort_order integer NOT NULL CHECK (sort_order >= 0), PRIMARY KEY (creature_id, sort_order));
--rollback INSERT INTO creature_actions (id, name, english_name, description, action_type, markdown) SELECT row_number() OVER (ORDER BY c.id, x.n), x.v ->> 'name', x.v ->> 'englishName', x.v ->> 'description', array_position(ARRAY['ACTION','REACTION','LEGENDARY','BONUS','LAIR','MYSTICAL'], x.v ->> 'actionType') - 1, COALESCE((x.v ->> 'markdown')::boolean, false) FROM creatures c CROSS JOIN LATERAL jsonb_array_elements(c.actions) WITH ORDINALITY AS x(v, n);
--rollback INSERT INTO creatures_actions (creature_id, actions_id, sort_order) SELECT c.id, row_number() OVER (ORDER BY c.id, x.n), x.n - 1 FROM creatures c CROSS JOIN LATERAL jsonb_array_elements(c.actions) WITH ORDINALITY AS x(v, n);
--rollback SELECT setval(pg_get_serial_sequence('creature_actions', 'id'), COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM creature_actions;
--rollback ALTER TABLE creatures_actions ADD CONSTRAINT FKnhhp1o5sog3haaky88ag9n1kp FOREIGN KEY (actions_id) REFERENCES creature_actions (id);
--rollback ALTER TABLE creatures_actions ADD CONSTRAINT FK8d41s9r0h9fbd75s726hu86wi FOREIGN KEY (creature_id) REFERENCES creatures (id);
--rollback CREATE INDEX ix_creatures_actions_actions_id ON creatures_actions (actions_id);
